-- BEGIN REVIEWED PREFLIGHT
-- Fail closed on function drift; this draft never enables rewards.
do $reviewed_preflight$
begin
 if coalesce((select enabled from versus_private.adventure_reward_rollout where singleton),false) then raise exception 'Pausá las recompensas antes de instalar esta revisión.';end if;
 if to_regprocedure('private.add_versus_recovery_word()') is null or md5(pg_get_functiondef(to_regprocedure('private.add_versus_recovery_word()'))) is distinct from 'af5e170ce1434282202243e6cbf3271c' then raise exception 'La función private.add_versus_recovery_word() cambió: detené la instalación y revisá el preflight.';end if;
 if to_regprocedure('versus_private.adventure_duel_actor(text)') is null or md5(pg_get_functiondef(to_regprocedure('versus_private.adventure_duel_actor(text)'))) is distinct from '31e1a5e7e75efd85dfe329434c71458f' then raise exception 'La función versus_private.adventure_duel_actor(text) cambió: detené la instalación y revisá el preflight.';end if;
 if to_regprocedure('versus_private.adventure_duel_letter(jsonb,text,text,timestamp with time zone)') is null or md5(pg_get_functiondef(to_regprocedure('versus_private.adventure_duel_letter(jsonb,text,text,timestamp with time zone)'))) is distinct from '44f210e6345f43b26f6d7fd683d4b5c3' then raise exception 'La función versus_private.adventure_duel_letter(jsonb,text,text,timestamp with time zone) cambió: detené la instalación y revisá el preflight.';end if;
 if to_regprocedure('versus_private.adventure_duel_view(jsonb,timestamp with time zone)') is null or md5(pg_get_functiondef(to_regprocedure('versus_private.adventure_duel_view(jsonb,timestamp with time zone)'))) is distinct from '174a33ac5d9ee80aa56b36977d663502' then raise exception 'La función versus_private.adventure_duel_view(jsonb,timestamp with time zone) cambió: detené la instalación y revisá el preflight.';end if;
 if to_regprocedure('versus_private.adventure_duel_word(jsonb,text)') is null or md5(pg_get_functiondef(to_regprocedure('versus_private.adventure_duel_word(jsonb,text)'))) is distinct from 'd3412eac542b7de3a18775152c9b537c' then raise exception 'La función versus_private.adventure_duel_word(jsonb,text) cambió: detené la instalación y revisá el preflight.';end if;
 if to_regprocedure('public.set_versus_challenge(uuid,text,text[])') is null or md5(pg_get_functiondef(to_regprocedure('public.set_versus_challenge(uuid,text,text[])'))) is distinct from 'e172af35064074b214ebe1a842836496' then raise exception 'La función public.set_versus_challenge(uuid,text,text[]) cambió: detené la instalación y revisá el preflight.';end if;
 if to_regprocedure('private.validate_versus_challenge_dictionary()') is null or md5(pg_get_functiondef(to_regprocedure('private.validate_versus_challenge_dictionary()'))) is distinct from 'f9ab8b5e2e85f8468f6e9e9a11917ddb' then raise exception 'La función private.validate_versus_challenge_dictionary() cambió: detené la instalación y revisá el preflight.';end if;
end $reviewed_preflight$;
