-- DRAFT: NOT INSTALLED. Both old dictionaries and every existing room/challenge are preserved.
-- New rooms opt into reviewed-v2 ONLY after a separately authorized rollout switch.
create table versus_private.word_category_rollout(singleton boolean primary key default true check(singleton),enabled boolean not null default false);
insert into versus_private.word_category_rollout values(true,false);
alter table versus_private.word_category_rollout enable row level security;
revoke all on versus_private.word_category_rollout from public,anon,authenticated,service_role;
create table versus_private.reviewed_word_dictionary(
 word_language text not null check(word_language in ('es','en','pt-BR')),
 theme_key text not null check(theme_key in ('paises','frutas','animales','comidas','profesiones','deportes','transportes','objetos','naturaleza','nombres','invertebrados')),
 word text not null check(char_length(word) between 3 and 12),word_key text not null,
 primary key(word_language,theme_key,word_key)
);
alter table versus_private.reviewed_word_dictionary enable row level security;
revoke all on versus_private.reviewed_word_dictionary from public,anon,authenticated,service_role;
