alter table public.versus_rooms add column word_bank_version text not null default 'legacy-v1' check(word_bank_version in ('legacy-v1','reviewed-v2'));
create table versus_private.word_bank_room_clients(room_id uuid not null references public.versus_rooms(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,primary key(room_id,user_id));
alter table versus_private.word_bank_room_clients enable row level security;
revoke all on versus_private.word_bank_room_clients from public,anon,authenticated,service_role;
create function private.pin_versus_word_bank() returns trigger language plpgsql security definer set search_path='' as $$
begin
 if TG_OP='INSERT' then
  new.word_bank_version:='legacy-v1';
 elsif new.word_bank_version is distinct from old.word_bank_version and not (
  old.word_bank_version='legacy-v1' and new.word_bank_version='reviewed-v2' and new.status in ('waiting','complete','preparing')
  and coalesce((select enabled from versus_private.word_category_rollout where singleton),false)
  and not exists(select 1 from public.versus_challenges where room_id=new.id)
  and not exists(select 1 from public.versus_matches where room_id=new.id)
  and (select count(*) from public.versus_players where room_id=new.id)=2
  and not exists(select 1 from public.versus_players p where p.room_id=new.id and not exists(select 1 from versus_private.word_bank_room_clients c where c.room_id=p.room_id and c.user_id=p.user_id))
 ) then
  raise exception 'El diccionario de una sala no puede cambiar durante la partida.' using errcode='22023';
 end if;
 return new;
end $$;
revoke all on function private.pin_versus_word_bank() from public,anon,authenticated,service_role;
create trigger pin_versus_word_bank before insert or update of word_bank_version on public.versus_rooms for each row execute function private.pin_versus_word_bank();
create function public.register_versus_word_bank(p_room_id uuid,p_version text) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid();r public.versus_rooms;
begin
 if u is null or not public.is_versus_room_member(p_room_id) then raise exception 'No perteneces a esta sala.' using errcode='42501';end if;
 if p_version is distinct from 'reviewed-v2' then raise exception 'Versión de palabras inválida.' using errcode='22023';end if;
 select * into strict r from public.versus_rooms where id=p_room_id for update;
 insert into versus_private.word_bank_room_clients(room_id,user_id) values(p_room_id,u) on conflict do nothing;
 if r.word_bank_version='legacy-v1' and r.status in ('waiting','complete','preparing')
  and coalesce((select enabled from versus_private.word_category_rollout where singleton),false)
  and not exists(select 1 from public.versus_challenges where room_id=r.id)
  and not exists(select 1 from public.versus_matches where room_id=r.id)
  and (select count(*) from public.versus_players where room_id=r.id)=2
  and not exists(select 1 from public.versus_players p where p.room_id=r.id and not exists(select 1 from versus_private.word_bank_room_clients c where c.room_id=p.room_id and c.user_id=p.user_id)) then
   update public.versus_rooms set word_bank_version='reviewed-v2' where id=r.id returning * into r;
 end if;
 return jsonb_build_object('wordBankVersion',r.word_bank_version);
end $$;
revoke all on function public.register_versus_word_bank(uuid,text) from public,anon,authenticated,service_role;
grant execute on function public.register_versus_word_bank(uuid,text) to authenticated;

CREATE OR REPLACE FUNCTION private.validate_versus_challenge_dictionary()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if (select word_bank_version from public.versus_rooms where id=new.room_id)='reviewed-v2' then
  if exists(select 1 from unnest(new.words) supplied(word) where not exists(select 1 from versus_private.reviewed_word_dictionary d join public.versus_rooms r on r.id=new.room_id where d.word_language=r.word_language and d.theme_key=new.theme_key and d.word_key=public.versus_letter_key(supplied.word))) then
   raise exception 'Una o más palabras no figuran en el diccionario de la temática.';
  end if;
  return new;
 end if;
  if exists (
    select 1
    from unnest(new.words) as supplied(word)
    where not exists (
      select 1
      from private.versus_word_dictionary as dictionary
      where (select word_language from public.versus_rooms where id=new.room_id)='es' and dictionary.theme_key = new.theme_key
        and dictionary.word_key = public.versus_letter_key(supplied.word)
    )
    and not exists (select 1 from versus_private.localized_dictionary d join public.versus_rooms r on r.id=new.room_id where d.word_language=r.word_language and d.theme_key=new.theme_key and d.word_key=public.versus_letter_key(supplied.word))
  ) then
    raise exception 'Una o más palabras no figuran en el diccionario de la temática.';
  end if;

  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION private.add_versus_recovery_word()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_room_id uuid;
  v_theme_key text;
  v_words text[];
  v_failed_word text;
  v_recovery_word text;
begin
  if new.current_word_index <> old.current_word_index + 1 then
    return new;
  end if;

  select m.room_id, challenge.theme_key, challenge.words
  into v_room_id, v_theme_key, v_words
  from public.versus_matches as m
  join public.versus_challenges as challenge
    on challenge.room_id = m.room_id
   and challenge.target_id = new.user_id
  where m.id = new.match_id
  for update of challenge;

  if new.completed_words = old.completed_words then
    v_failed_word := v_words[old.current_word_index + 1];
    new.last_failed_word := v_failed_word;

    if new.lives > 0 and cardinality(v_words) < 9 then
      select dictionary.word
      into v_recovery_word
      from (
 select d.theme_key,d.word,d.word_key from private.versus_word_dictionary d join public.versus_rooms r on r.id=v_room_id where r.word_language='es' and r.word_bank_version='legacy-v1'
 union all select d.theme_key,d.word,d.word_key from versus_private.localized_dictionary d join public.versus_rooms r on r.id=v_room_id where d.word_language=r.word_language and r.word_bank_version='legacy-v1'
 union all select d.theme_key,d.word,d.word_key from versus_private.reviewed_word_dictionary d join public.versus_rooms r on r.id=v_room_id where d.word_language=r.word_language and r.word_bank_version='reviewed-v2'
 ) as dictionary
      where dictionary.theme_key = v_theme_key
        and not exists (
          select 1
          from unnest(v_words) as existing(word)
          where public.versus_letter_key(existing.word) = dictionary.word_key
        )
      order by random()
      limit 1;

      if v_recovery_word is null then
        raise exception 'No quedan palabras de recuperación para esta temática.';
      end if;

      update public.versus_challenges
      set words = array_append(words, v_recovery_word),
          updated_at = now()
      where room_id = v_room_id and target_id = new.user_id;
    end if;
  end if;

  -- Cinco palabras acertadas siguen siendo el objetivo. El índice también cuenta
  -- las falladas, por eso no debe finalizar el recorrido por sí solo.
  if new.lives > 0 and new.completed_words < 5 then
    new.finished := false;
    new.finish_reason := null;
  end if;

  return new;
end;
$function$
;
CREATE OR REPLACE FUNCTION public.set_versus_challenge(p_room_id uuid, p_theme_key text, p_words text[])
 RETURNS versus_rooms
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid := auth.uid();
  v_target_id uuid;
  v_room public.versus_rooms;
  v_words text[];
  v_player_count integer;
  v_ready_count integer;
begin
  perform private.assert_versus_available(
    array(select user_id from public.versus_players where room_id=p_room_id) || array[auth.uid()],p_room_id);
  if v_user_id is null then
    raise exception 'Debes iniciar una sesión antes de preparar el desafío.';
  end if;

  select * into v_room
  from public.versus_rooms
  where id = p_room_id
  for update;

  if not found or not public.is_versus_room_member(p_room_id) then
    raise exception 'No perteneces a esta sala.';
  end if;
  if v_room.status not in ('preparing') then
    raise exception 'La sala todavía no está lista para recibir palabras.';
  end if;

  if p_theme_key is null
 or (v_room.word_bank_version='legacy-v1' and p_theme_key not in ('paises','frutas','animales','comidas','profesiones','deportes','transportes','objetos','naturaleza','nombres'))
 or (v_room.word_bank_version='reviewed-v2' and not exists(select 1 from versus_private.reviewed_word_dictionary where word_language=v_room.word_language and theme_key=p_theme_key)) then
    raise exception 'La temática elegida no es válida.';
  end if;

  if coalesce(cardinality(p_words),0) <> 5 or array_ndims(p_words) <> 1 then
    raise exception 'Debes enviar exactamente cinco palabras.';
  end if;

  select array_agg(upper(normalize(btrim(word),NFC)) order by position)
  into v_words
  from unnest(p_words) with ordinality as supplied(word, position);

  if exists (
    select 1 from unnest(v_words) as word
    where word is null or char_length(word) not between 3 and 12
       or word !~ case v_room.word_language when 'en' then '^[A-Z]+$' when 'pt-BR' then '^[A-ZÁÀÂÃÉÊÍÓÔÕÚÜÇ]+$' else '^[A-ZÁÉÍÓÚÜÑ]+$' end
  ) then
    raise exception 'Las palabras deben tener entre 3 y 12 letras, sin espacios ni números.';
  end if;

  if (
    select count(distinct public.versus_letter_key(word))
    from unnest(v_words) as word
  ) <> 5 then
    raise exception 'Las cinco palabras deben ser diferentes.';
  end if;

  select user_id into v_target_id
  from public.versus_players
  where room_id = p_room_id and user_id <> v_user_id;
  if not found then raise exception 'El rival ya no está en la sala.'; end if;

  insert into public.versus_challenges (
    room_id, owner_id, target_id, theme_key, words
  ) values (
    p_room_id, v_user_id, v_target_id, p_theme_key, v_words
  )
  on conflict (room_id, owner_id) do update
  set target_id = excluded.target_id,
      theme_key = excluded.theme_key,
      words = excluded.words,
      updated_at = now();

  update public.versus_players
  set theme_key = p_theme_key, preparation_ready = true
  where room_id = p_room_id and user_id = v_user_id;

  select count(*), count(*) filter (where preparation_ready)
  into v_player_count, v_ready_count
  from public.versus_players
  where room_id = p_room_id;

  update public.versus_rooms
  set status = case
    when v_player_count = 2 and v_ready_count = 2 then 'playing'
    else 'preparing'
  end
  where id = p_room_id
  returning * into v_room;

  return v_room;
end;
$function$
;
-- BEGIN ADVENTURE BANK V2
create view versus_private.reviewed_adventure_duel_words with(security_invoker=true) as
 select word_language as language,theme_key as theme,(row_number() over(partition by word_language,theme_key order by word_key collate "C")-1)::integer as word_id,word,word_key from versus_private.reviewed_word_dictionary;
revoke all on versus_private.reviewed_adventure_duel_words from public,anon,authenticated,service_role;
create function versus_private.adventure_duel_bank(p_language text,p_version text) returns table(language text,theme text,word_id integer,word text,word_key text)
language sql stable security definer set search_path='' as $$
 select w.* from versus_private.adventure_duel_words w where w.language=p_language and p_version='legacy-v1'
 union all select w.* from versus_private.reviewed_adventure_duel_words w where w.language=p_language and p_version='reviewed-v2'
$$;
revoke all on function versus_private.adventure_duel_bank(text,text) from public,anon,authenticated,service_role;
create or replace function versus_private.adventure_duel_actor(p_language text) returns jsonb language plpgsql security definer set search_path='' as $$
declare theme_ text;words_ jsonb;version_ text:=case when coalesce((select enabled from versus_private.word_category_rollout where singleton),false) then 'reviewed-v2' else 'legacy-v1' end;
begin
 select theme into strict theme_ from versus_private.adventure_duel_bank(p_language,version_) group by theme order by random() limit 1;
 select jsonb_agg(word_id) into words_ from(select word_id from versus_private.adventure_duel_bank(p_language,version_) where theme=theme_ order by gen_random_uuid() limit 5)q;
 if jsonb_array_length(words_)<>5 then raise exception 'Banco de duelo incompleto.';end if;
 return jsonb_build_object('bankVersion',version_,'theme',theme_,'words',words_,'index',0,'letters','[]'::jsonb,'errors',0,'lives',5,'completed',0,'charge',0,'hint','','finished',false,'effect','','effect_until',null,'deadline',null);
end $$;
create or replace function versus_private.adventure_duel_word(p_state jsonb,p_actor text) returns text language sql stable security definer set search_path='' as $$
 select w.word_key from versus_private.adventure_duel_bank(p_state->>'language',coalesce(p_state->p_actor->>'bankVersion','legacy-v1')) w where w.language=p_state->>'language' and w.theme=p_state->p_actor->>'theme' and w.word_id=(p_state->p_actor->'words'->>((p_state->p_actor->>'index')::integer))::integer
$$;
create or replace function versus_private.adventure_duel_letter(p_state jsonb,p_actor text,p_letter text,p_now timestamptz) returns jsonb
language plpgsql security definer set search_path='' as $$
declare s jsonb:=p_state;a jsonb:=s->p_actor;other_ text:=case when p_actor='player' then 'npc' else 'player' end;b jsonb:=s->other_;word_ text;letters_ text[];won boolean;failed boolean;extra_ integer;amount_ integer;idx integer;
begin
 if (s->>'finished')::boolean or (a->>'finished')::boolean then return s;end if;
 word_:=versus_private.adventure_duel_word(s,p_actor);if word_ is null then raise exception 'No hay palabra activa.';end if;
 if p_letter is null or length(p_letter)<>1 or position(p_letter in case when s->>'language'='es' then 'QWERTYUIOPASDFGHJKLÑZXCVBNM' else 'QWERTYUIOPASDFGHJKLZXCVBNM' end)=0 then raise exception 'Letra inválida.' using errcode='22023';end if;
 if a->'letters' @> jsonb_build_array(p_letter) then return s;end if;
 a:=jsonb_set(a,'{letters}',a->'letters'||to_jsonb(p_letter));
 amount_:=length(word_)-length(replace(word_,p_letter,''));
 if amount_>0 then a:=jsonb_set(a,'{charge}',to_jsonb(least(8,(a->>'charge')::integer+amount_)));else a:=jsonb_set(a,'{errors}',to_jsonb((a->>'errors')::integer+1));end if;
 if a->>'hint'=p_letter then a:=jsonb_set(a,'{hint}','""');end if;
 select coalesce(array_agg(value),'{}') into letters_ from jsonb_array_elements_text(a->'letters');
 won:=not exists(select 1 from generate_series(1,length(word_)) i where not substr(word_,i,1)=any(letters_));failed:=(a->>'errors')::integer>=6;
 s:=versus_private.adventure_duel_event(s,jsonb_build_object('type','letter','actor',p_actor,'letter',p_letter,'correct',amount_>0));
 if won or failed then
  idx:=(a->>'index')::integer+1;a:=a||jsonb_build_object('index',idx,'letters','[]'::jsonb,'errors',0,'hint','');
  if won then a:=jsonb_set(a,'{completed}',to_jsonb((a->>'completed')::integer+1));b:=jsonb_set(b,'{lives}',to_jsonb((b->>'lives')::integer-1));
  else
   a:=jsonb_set(a,'{lives}',to_jsonb((a->>'lives')::integer-1));
   if (a->>'lives')::integer>0 then
    select w.word_id into extra_ from versus_private.adventure_duel_bank(s->>'language',coalesce(a->>'bankVersion','legacy-v1')) w where w.language=s->>'language' and w.theme=a->>'theme' and not (a->'words' @> to_jsonb(array[w.word_id])) order by gen_random_uuid() limit 1;
    if extra_ is not null then a:=jsonb_set(a,'{words}',a->'words'||to_jsonb(extra_));end if;
   end if;
  end if;
  if (a->>'completed')::integer>=5 then a:=jsonb_set(a,'{finished}','true');end if;
  if a->>'effect'='forced_miss' then a:=a||jsonb_build_object('effect','','effect_until',null);end if;
  s:=versus_private.adventure_duel_event(s,jsonb_build_object('type','word','actor',p_actor,'correct',won,'reveal',case when failed then word_ else null end));
 end if;
 s:=jsonb_set(jsonb_set(s,array[p_actor],a),array[other_],b);
 return versus_private.adventure_duel_resolve(s,p_now);
end $$;
create or replace function versus_private.adventure_duel_view(p_state jsonb,p_now timestamptz) returns jsonb
language plpgsql security definer set search_path='' as $$
declare s jsonb:=p_state;result jsonb:=s-array['pending','config','player','npc'];actor_ text;a jsonb;word_ text;display_ text;mask_ jsonb;until_ timestamptz;
begin
 result:=result||jsonb_build_object('character',s->'config'->>'character');
 foreach actor_ in array array['player','npc'] loop
  a:=s->actor_;word_:=versus_private.adventure_duel_word(s,actor_);
  select w.word into display_ from versus_private.adventure_duel_bank(s->>'language',coalesce(a->>'bankVersion','legacy-v1')) w where w.language=s->>'language' and w.theme=a->>'theme' and w.word_id=(a->'words'->>((a->>'index')::integer))::integer;
  select coalesce(jsonb_agg(case when a->'letters' @> jsonb_build_array(substr(word_,i,1)) then to_jsonb(case when actor_='npc' then '?' else substr(display_,i,1) end) else 'null'::jsonb end order by i),'[]'::jsonb) into mask_ from generate_series(1,coalesce(length(word_),0)) i;
  until_:=case when (s->>'finished')::boolean then (s->>'finished_at')::timestamptz else p_now end;
  result:=jsonb_set(result,array[actor_],(a-'words')||jsonb_build_object('mask',mask_,'remaining',case when not (s->>'started')::boolean then 240 else greatest(0,ceil(extract(epoch from (a->>'deadline')::timestamptz-until_))::integer) end,'effectRemaining',greatest(0,ceil(extract(epoch from (a->>'effect_until')::timestamptz-p_now)*1000))::integer,'effect',case when (a->>'effect_until')::timestamptz>p_now then a->>'effect' else '' end));
 end loop;
 return result;
end $$;
-- No rollout flag is enabled by this migration. Existing banks and live match arrays are untouched.
notify pgrst, 'reload schema';
